def solution(input_str):
    n, x = map(int, input_str.strip().split())

    # The problem requires finding the largest base b where 1 < b < x
    # such that there exists a rotatable number of length n in base b.
    # Based on the mathematical pattern, this requires:
    # 1. n + 1 should be prime
    # 2. b should be a primitive root modulo (n + 1)

    p = n + 1

    # Check if p is prime
    if p < 2:
        return "-1\n"

    def is_prime(num):
        if num < 2:
            return False
        if num == 2:
            return True
        if num % 2 == 0:
            return False
        i = 3
        while i * i <= num:
            if num % i == 0:
                return False
            i += 2
        return True

    if not is_prime(p):
        return "-1\n"

    # Modular exponentiation
    def power(a, b, m):
        result = 1
        a %= m
        while b > 0:
            if b % 2 == 1:
                result = (result * a) % m
            a = (a * a) % m
            b //= 2
        return result

    # Prime factorization of n = p - 1
    prime_factors = set()
    temp = n
    d = 2
    while d * d <= temp:
        while temp % d == 0:
            prime_factors.add(d)
            temp //= d
        d += 1
    if temp > 1:
        prime_factors.add(temp)

    # Find largest b in (1, x) that is a primitive root mod p
    for b in range(x - 1, 1, -1):
        is_primitive = True
        for q in prime_factors:
            if power(b, n // q, p) == 1:
                is_primitive = False
                break
        if is_primitive:
            return f"{b}\n"

    return "-1\n"
