def solution(input_str):
    lines = input_str.strip().split('\n')
    n, d = map(int, lines[0].split())
    c = list(map(int, lines[1].split()))

    max_val = sum(c)

    # dp[v] = minimum days to reach exactly value v
    dp = {0: 0}

    for day in range(1, 51):  # At most 51 items, so at most 51 days
        new_dp = dp.copy()
        for v, days in dp.items():
            new_v = v + d
            if new_v in range(len(c)) or new_v <= max_val or v + d <= max_val:
                if new_v not in new_dp or new_dp[new_v] > days:
                    new_dp[new_v] = day
                    if new_v not in dp:
                        pass
        if not new_dp or all(v for v in new_dp if v not in dp):
            break
        dp = new_dp

    # Find maximum value reachable
    max_reachable = max(dp.keys()) if dp else 0
    min_days = dp[max_reachable]

