        if (cur_r, cur_c) == (target_r, target_c):
            return []

        from collections import deque
        queue = deque([(cur_r, cur_c, [])])
        visited = [[False] * n for _ in range(n)]
        visited[cur_r][cur_c] = True

        while queue:
            r, c, path = queue.popleft()
            found = False

            for dr, dc, d in [(-1, 0, 'U'), (1, 0, 'D'), (0, -1, 'L'), (0, 1, 'R')]:
                nr, nc = r + dr, c + dc
                if 0 <= nr < n and 0 <= nc < n and not visited[nr][nc]:
                    visited[nr][nc] = True
                    # Check if we can move in this direction
                    if can_see_light(r, c, dr, dc, n):
                        new_path = path + [d]
                        queue.append((nr, nc, new_path))

            # Check if we found target
            if (r, c) == (target_r, target_c):
                return path
        return None

    curr_r, curr_c = x0, y0

    max_actions = 3000000
    action_count = 0

    for tr, tc in lit_cells:
        path = find_path(curr_r, curr_c, tr, tc)
        if path is None:
            return "NO"

        for d in path:
            actions.append(d)
            action_count += 1

        # Turn off light at target room
        if grid[tr][tc] == 1:
            actions.append('2')
            action_count += 1
            grid[tr][tc] = 0

        curr_r, curr_c = tr, tc

        if action_count > max_actions:
            return "NO"

    # Return to start
    while curr_r != x0 or curr_c != y0:
        for dr, dc, d in [(-1, 0, 'U'), (1, 0, 'D'), (0, -1, 'L'), (0, 1, 'R')]:
            nr, nc = curr_r + dr, curr_c + dc
            if 0 <= nr < n and 0 <= nc < n and (nr == x0 and nc == y0):
                actions.append(d)
                action_count += 1
                curr_r, curr_c = nr, nc

        if curr_r != x0 or curr_c != y0:
            # If we can't return, revisit and try again
            return "NO"

    # Turn off light at start if still on
    if grid[x0][y0] == 1:
        actions.append('2')

    if action_count > max_actions:
        return "NO"

