def solution(input_str):
    n, k, m = map(int, input_str.strip().split())

    # If we need to visit only 1 planet, any starting planet works
    if k == 1:
        return str(n % MOD)

    from functools import lru_cache

    @lru_cache(maxsize=None)
    def count_ways(current, steps_left, visited_tuple):
        """
        Count ways to complete a sequence of length k ending at 'current'
        with 'steps_left' more planets to visit, given 'visited_tuple' planets are already visited.
        """
        if steps_left == 0:
            return 1

        count = 0
        # Next planet must be in range [1, min(n, current + m)]
        max_next = min(n, current + m)

        for next_plant in range(1, max_next + 1):
            if next_plant not in visited_tuple:
                new_visited = visited_tuple + (next_plant,)
                count = (count + count_ways(next_plant, steps_left - 1, new_visited)) % MOD

        return count

    total = 0
    for start in range(1, n + 1):
        visited = (start,)
        total = (total + count_ways(start, k - 1, visited)) % MOD

    return str(total)
