from io import StringIO

def solution(input_str):
    data = input_str.strip().split('\n')
    if not data:
        return ''

    t = int(data[0])
    queries = []
    for i in range(1, t + 1):
        if i < len(data):
            queries.append(int(data[i]))

    # Precompute Fibonacci numbers up to 10^18 (using problem's F1=1, F2=2)
    # F1=1, F2=2, F3=3, F4=5, F5=8, F6=13, F7=21, ...
    fib = [1, 2]
    while fib[-1] <= 2 * 10**18:
        fib.append(fib[-1] + fib[-2])

    def count_decompositions(n):
        """Count the number of ways to represent n as sum of distinct Fibonacci numbers"""
        if n <= 0:
            return 0

        # Find Zeckendorf representation (greedy approach)
        zek_indices = []
        temp = n
        for i in range(len(fib) - 1, -1, -1):
            if fib[i] <= temp:
                zek_indices.append(i + 1)  # 1-indexed
                temp -= fib[i]

        if temp > 0:
            return 0  # Shouldn't happen with valid input

        if not zek_indices:
            return 0

        # Calculate the answer based on gaps
        k = len(zek_indices)
        result = 2 ** (k - 1)

        # Calculate gaps between consecutive indices
        gaps = []
        for i in range(1, k):
            gap = zek_indices[i-1] - zek_indices[i] - 1
            gaps.append(gap)

        # For each gap, multiply by appropriate Fibonacci number
        for gap_id, gap in enumerate(gaps):
            # F_{gap + 1} based on the sequence (F1=1, F2=2...)
            index_to_use = gap + 1
            if index_to_use < len(fib):
                result *= fib[index_to_use - 1]  # Adjust for 0-indexed fib array
            elif index_to_use == len(fib):
                result *= fib[-1]
            else:
                # Need to compute farther Fibonacci number
                new_fib = [0] * (index_to_use + 5)
                new_fib[0] = 1
                new_fib[1] = 2
                for j in range(2, index_to_use + 1):
                    new_fib[j] = new_fib[j-1] + new_fib[j-2]
                result *= new_fib[index_to_use - 1]

        return result

    results = []
    for n in queries:
        results.append(str(count_decompositions(n)))

    return '\n'.join(results)


