```python
def solution(n_k):
    n, k = map(int, n_k.strip().split())
    k = int(k)

    # For bounded computation
    if n <= 20:
        strings = [format(i, f'0{n}b') for i in range(1 << n)]

        def get_rep(s):
            flips = [s, s[::-1]]
            fl = ''.join('1' if c == '0' else '0' for c in s)
            flips.extend([fl, fl[::-1]])
            return min(flips)

        reps = []
        seen = set()
        for s in strings:
            r = get_rep(s)
            if r not in seen:
                seen.add(r)
                reps.append(r)

        reps.sort()

        return "-1" if k > len(reps) else reps[k - 1]
    else:
        # For large n: k-th representative follows pattern
        k -= 1
        mid = (n + 1) // 2
        idx = 0

        for i in range(mid):
            if (k >> i) & 1:
                idx += 2**(mid - 1 - i)

        if idx > 1 << mid:
            return "-1"

        res = []
        for i in range(mid):
            if idx & (1 << i):
                res.append('1')
            else:
                res.append('0')

        res.extend(res)
        if n % 2 == 1:
            res.pop()

        return ''.join(res)
